static int idata_eq(const char *a, const char *b)
{
    while (*a && *a == *b) { a++; b++; }
    return *a == *b;
}

uint32_t *icons_data_find(const char *name)
{
    if (!name)
        return (uint32_t *)0;
    for (int i = 0; icon_data_table[i].name; i++)
        if (idata_eq(icon_data_table[i].name, name))
            return icon_data_table[i].pixels;
    return (uint32_t *)0;
}
